<?php
namespace App\Controllers;

use App\Core\Auth;use App\Core\Csrf;use App\Core\View;use App\Models\AuditLog;use App\Models\Employee;use App\Models\MasterData;use App\Models\Signer;

final class AdminEmployeeController
{
    public function index(): void{Auth::requireAdmin();View::render('admin/employees/index',['employees'=>Employee::all(),'teams'=>MasterData::workTeams()]);}
    public function store(): void{Auth::requireAdmin();Csrf::validate($_POST['_token']??null);$d=$this->data();if($d['name']===''){$_SESSION['flash_error']='Nama pegawai wajib diisi.';header('Location:/admin/employees');exit;}$id=Employee::create($d,(int)Auth::id());$employee=Employee::find($id);$auto=Signer::createAutoForEmployee($employee,(int)Auth::id());AuditLog::write(Auth::id(),'CREATE_EMPLOYEE','employee',$id,['name'=>$d['name'],'signer_created'=>$auto['created']]);$_SESSION['flash_success']=$auto['passkey']?'Pegawai ditambahkan. Passkey otomatis: '.$auto['passkey'].' (simpan sekarang; passkey tersimpan dalam bentuk hash).':'Pegawai ditambahkan.';header('Location:/admin/employees');exit;}
    public function update(string $id): void{Auth::requireAdmin();Csrf::validate($_POST['_token']??null);if(!Employee::find((int)$id)){http_response_code(404);View::render('errors/404');return;}$d=$this->data();if($d['name']===''){$_SESSION['flash_error']='Nama pegawai wajib diisi.';header('Location:/admin/employees');exit;}Employee::update((int)$id,$d,(int)Auth::id());AuditLog::write(Auth::id(),'UPDATE_EMPLOYEE','employee',(int)$id);$_SESSION['flash_success']='Data pegawai diperbarui.';header('Location:/admin/employees');exit;}
    public function toggle(string $id): void{Auth::requireAdmin();Csrf::validate($_POST['_token']??null);$e=Employee::find((int)$id);if(!$e){http_response_code(404);View::render('errors/404');return;}$active=!((bool)$e['is_active']);Employee::setActive((int)$id,$active,(int)Auth::id());$_SESSION['flash_success']=$active?'Pegawai diaktifkan.':'Pegawai dinonaktifkan.';header('Location:/admin/employees');exit;}
    public function makeSigner(string $id): void{Auth::requireAdmin();Csrf::validate($_POST['_token']??null);$e=Employee::find((int)$id);if(!$e){http_response_code(404);View::render('errors/404');return;}$auto=Signer::createAutoForEmployee($e,(int)Auth::id());$_SESSION['flash_success']=$auto['passkey']?'Penanda tangan dibuat. Passkey otomatis: '.$auto['passkey'].' (simpan sekarang).':'Pegawai ini sudah menjadi penanda tangan.';header('Location:/admin/signers');exit;}
    public function importCsv(): void{Auth::requireAdmin();Csrf::validate($_POST['_token']??null);$f=$_FILES['csv_file']??null;if(!$f||($f['error']??1)!==UPLOAD_ERR_OK){$_SESSION['flash_error']='Pilih berkas CSV.';header('Location:/admin/employees');exit;}if(($f['size']??0)>2*1024*1024){$_SESSION['flash_error']='CSV maksimal 2 MB.';header('Location:/admin/employees');exit;}$h=fopen($f['tmp_name'],'r');if(!$h){$_SESSION['flash_error']='CSV tidak dapat dibaca.';header('Location:/admin/employees');exit;}$header=array_map(fn($v)=>strtolower(trim((string)$v)),fgetcsv($h)?:[]);$count=0;while(($row=fgetcsv($h))!==false){$r=array_combine($header,array_pad($row,count($header),''));if(!$r||trim($r['name']??'')==='')continue;$teamId=0;$teamName=trim($r['work_team']??'');if($teamName!==''){foreach(MasterData::workTeams() as $t)if(strcasecmp($t['name'],$teamName)===0){$teamId=(int)$t['id'];break;}}$newId=Employee::create(['name'=>trim($r['name']),'nip'=>trim($r['nip']??''),'position'=>trim($r['position']??''),'work_team_id'=>$teamId,'email'=>trim($r['email']??'')],(int)Auth::id());$newEmployee=Employee::find($newId);Signer::createAutoForEmployee($newEmployee,(int)Auth::id());$count++;}fclose($h);$_SESSION['flash_success']=$count.' data pegawai diimpor.';header('Location:/admin/employees');exit;}
    private function data(): array{return ['name'=>trim($_POST['name']??''),'nip'=>trim($_POST['nip']??''),'position'=>trim($_POST['position']??''),'work_team_id'=>(int)($_POST['work_team_id']??0),'email'=>trim($_POST['email']??'')];}
}